// Real jQuery via npm, exposed as window.jQuery/window.$ for the vendored
// admin theme's classic (non-module) plugin scripts — DataTables,
// bootstrap.min.js, etc. — which all expect a global jQuery to already exist.
// This file itself is missing from the repo's public/build/js/ output (a
// pre-existing gap, not something this session's other work touched); the
// filename is kept as jquery.min.js so it lands at the exact path
// layouts/footerjs.blade.php already references, with no Blade changes needed.
import jQuery from 'jquery';

window.jQuery = window.$ = jQuery;
